fn user_card(name: Str, age: Int, email: Str) -> Str {
  return format("{} ({}): {}", name, age, email);
}

fn progress_bar(current: Int, total: Int) -> Str {
  let percent = (current * 100) / total;
  return format1("{}%", percent);
}

fn main() -> Int {
  let greeting = format1("Hello, {}!", "XIOM");
  return greeting.len();
}
